def packages(items,kind):
 result=''
 for i,p in enumerate(items):
  if kind=='website':
   msg=f"Hello RYAR Canvas! I'm interested in the Website Development service.\n\nSelected Package: {p['name']}\nPackage Price: ${p['price']} USD\nHosting Duration: {p['duration']}\nNumber of Websites: {p['quantity']}\n\nPlease confirm the package inclusions, domain and hosting terms, estimated delivery time, and the next steps."
   details=f'<span>◷ &nbsp;{p["duration"]} hosting</span><span>▤ &nbsp;{p["quantity"]} {"website" if p["quantity"]=="1" else "websites"}</span>'
  else:
   msg=f"Hello RYAR Canvas! I'm interested in your E-commerce Website + Custom Admin Panel service.\n\nSelected Package: {p['name']}\nPackage Price: ${p['price']} USD\nHosting Duration: {p['duration']}\n\n"+('Please confirm whether I should choose 18 months or 24 months of hosting. ' if i==1 else '')+'Please confirm the included store features, custom admin panel scope, technical architecture, payment gateway options, hosting details, payment and project-start information, and the next steps.'
   details=f'<span>◷ &nbsp;{p["duration"]} hosting</span><span>▤ &nbsp;Scope to be confirmed</span>'
  result+=f'<article class="price-card"><span class="price-index">PACKAGE {chr(65+i)}</span><h3>{p["name"]}</h3><div class="price">${p["price"]} <small>USD</small></div><p>{p["description"]}</p><div class="price-details">{details}</div>{button("Choose This Package",wa(msg),"outline", "data-event=\"package_selection\"")}</article>'
 return result
