for filename,name,title,desc,cta in future:
 msg=f"Hello RYAR Canvas! I'm interested in {name}. Please share updates and let me know how I can express my interest."
 body=f'''<section class="future-page"><div class="container"><a class="back-link" href="../index.html#coming-soon">← Back to coming soon</a><div class="future-grid"><div class="future-copy">{eyebrow('COMING SOON / '+esc(name.upper()))}<h1>{title}</h1><p>{desc}</p><div class="future-art"><span>✳</span><div>Good things<br><em>are taking shape.</em></div><small>IN THE WORKS / RYAR CANVAS</small></div></div><div class="form-card"><span class="price-index">BE PART OF WHAT’S NEXT</span><h2>{cta}</h2><p>Leave your details when registration is connected, or reach out to us directly on WhatsApp.</p><form class="interest-form" data-service="{esc(name)}" novalidate><label for="email">Email address <span>(required)</span></label><input id="email" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="name">Name <span>(optional)</span></label><input id="name" name="name" type="text" autocomplete="name" placeholder="Your name"><label for="interest">Area of interest <span>(optional)</span></label><input id="interest" name="interest" type="text" placeholder="What interests you?"><label class="consent"><input type="checkbox" name="consent" required><span>I agree to the use of my information for updates about {esc(name)}.</span></label><p class="privacy-note">We’ll use submitted information for this early-access purpose. Read our <a href="../privacy.html">privacy policy</a>.</p><button class="btn btn-primary form-submit" type="submit" disabled>{cta} <span aria-hidden="true">↗</span></button><noscript><p>Registration requires JavaScript. Please use the WhatsApp alternative below.</p></noscript><p class="form-status" role="status" aria-live="polite">Early-access registration is not yet connected. Please use WhatsApp to express your interest.</p></form><a class="text-link" href="{esc(wa(msg))}">Express interest on WhatsApp ↗</a></div></div></div></section>'''
 save('coming-soon/'+filename,name+' — Coming Soon | RYAR Canvas',desc,body,msg)
privacy='''<section class="legal-page container"><a class="back-link" href="index.html">← Back to home</a><div class="legal-content">'''+eyebrow('THE DETAILS')+'''<h1>Privacy <em>policy.</em></h1><p class="legal-intro">A practical starter policy for this website. Business-specific legal details should be reviewed and confirmed before publication.</p><h2>Information you choose to share</h2><p>When an early-access form is connected, it may collect your email address and optional name and area of interest, with your consent, to contact you about the service you selected. Registration is not connected until an endpoint is configured. Please do not submit sensitive information.</p><h2>WhatsApp and Instagram</h2><p>Links to WhatsApp and Instagram take you to third-party services. Your interactions there are subject to those providers’ own privacy policies. Information you share with us through those services will be used to respond to your inquiry and discuss the requested services.</p><h2>Form providers and analytics</h2><p>A configured form provider receives submissions under its own terms. No analytics provider or tracking ID is configured in this site by default. If one is added, review applicable consent requirements and update this policy before enabling it.</p><h2>Retention and your choices</h2><p>Retention periods, the identity of the business data controller, and any applicable rights and contact procedures must be confirmed by the business. To ask about information you shared, contact us via <a href="'''+esc(wa(general))+'''">WhatsApp</a>.</p><h2>Changes</h2><p>We may update this policy as the website or its integrations change. Review it before submitting information.</p></div></section>'''
save('privacy.html','Privacy Policy | RYAR Canvas','Read the RYAR Canvas website privacy policy and information about contact and early-access forms.',privacy)
terms='''<section class="legal-page container"><a class="back-link" href="index.html">← Back to home</a><div class="legal-content">'''+eyebrow('THE DETAILS')+'''<h1>Terms of <em>service.</em></h1><p class="legal-intro">These are starter website terms. The business should confirm its legal identity, governing law, and project-specific terms before publication.</p><h2>Using this website</h2><p>This website describes RYAR Canvas services for general information. You agree not to misuse the site or interfere with its operation.</p><h2>Service inquiries and packages</h2><p>A WhatsApp inquiry or package selection is not a payment, confirmed order, or binding project agreement. Deliverables, prices, hosting and domain terms, timelines, payment arrangements, and other conditions must be agreed separately before work starts.</p><h2>Prices and third-party costs</h2><p>Published package prices are in USD and apply to the stated scope and hosting period, subject to confirmation. Renewals, integrations, transaction charges, taxes, maintenance, and other third-party services may incur additional costs.</p><h2>Third-party services</h2><p>External websites and providers, including WhatsApp, Instagram, hosting and advertising platforms, have their own terms. We do not guarantee advertising approval, campaign performance, or the availability of third-party services.</p><h2>Intellectual property and project terms</h2><p>Rights to project deliverables, revisions, cancellations, refunds, and support are subject to the specific agreement reached with each client. Please confirm these details before payment.</p><h2>Questions</h2><p>Contact us on <a href="'''+esc(wa(general))+'''">WhatsApp</a> to discuss these terms or a project.</p></div></section>'''
save('terms.html','Terms of Service | RYAR Canvas','Read the starter website terms and learn how RYAR Canvas service inquiries and project agreements work.',terms)
notfound=f'''<section class="not-found container">{eyebrow('404 / PAGE NOT FOUND')}<h1>Looks like this idea<br><em>took a wrong turn.</em></h1><p>The page you’re looking for isn’t here. Let’s get you back on track.</p>{button('Back to Home','index.html')}</section>'''
save('404.html','Page Not Found | RYAR Canvas','The page you requested could not be found. Return to RYAR Canvas.',notfound)
(P/'CNAME').write_text('riarcanvas.online\n')
(P/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: https://riarcanvas.online/sitemap.xml\n')
urls=['','services/website-development.html','services/ecommerce-development.html','services/digital-marketing.html','coming-soon/ai-calling-agent.html','coming-soon/automated-lead-generation.html','coming-soon/academy.html','privacy.html','terms.html']
(P/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n'+''.join('<url><loc>https://riarcanvas.online/'+u+'</loc></url>\n' for u in urls)+'</urlset>\n')
